const CATS=['Onshore structure','New building','Conversion','Repairing'],ROM=['I','II','III','IV','V'],CUP=['ONSHORE STRUCTURE','NEW BUILDING','CONVERSION','REPAIRING'];
const catL=c=>t('c'+CATS.indexOf(c));
