let tessP=null;const loadT=()=>typeof Tesseract!=='undefined'?Promise.resolve():tessP||(tessP=new Promise((ok,no)=>{const sc=document.createElement('script');sc.src='https://cdn.jsdelivr.net/npm/tesseract.js@7.0.0/dist/tesseract.min.js';sc.onload=ok;sc.onerror=()=>{tessP=null;no(new Error('tesseract.js'))};document.head.appendChild(sc)}));
