async function shrink(f){if(!/^image\/(png|jpeg|webp|bmp)$/.test(f.type)||typeof createImageBitmap!=='function')return f;try{const bm=await createImageBitmap(f),sc=Math.min(1,2400/Math.max(bm.width,bm.height)),cv=document.createElement('canvas');cv.width=Math.round(bm.width*sc);cv.height=Math.round(bm.height*sc);cv.getContext('2d').drawImage(bm,0,0,cv.width,cv.height);const b=await new Promise(r=>cv.toBlob(r,'image/webp',0.85));if(b&&b.type==='image/webp'&&b.size<f.size)return new File([b],(f.name||'image').replace(/\.\w+$/,'')+'.webp',{type:'image/webp'})}catch(e){}return f}
