S.up++;render();try{const x=await upload(f,name);ed.files.push(Object.assign(x,{cat:'other'}));if(S.edit===ed){S.view=ed.files.length-1;ok=true}}catch(e){if(e.big)S.msg=[e.message];else S.toast=t('up_err',name,e.message)}finally{S.up--;render()}
